    from collections import defaultdict

    x_count = defaultdict(list)
    y_count = defaultdict(list)

    for i, (x, y) in enumerate(points):
        x_count[x].append(i)
        y_count[y].append(i)

    triangles = 0

    # Check for right triangles where legs are parallel to axes
    for x, indices in x_count.items():
        for i in range(len(indices)):
            for j in range(i + 1, len(indices)):
                y1, y2 = points[indices[i]][1], points[indices[j]][1]
                if y1 != y2:
                    triangles += len(y_count[y1]) - 1
                    triangles += len(y_count[y2]) - 1

    for y, indices in y_count.items():
        for i in range(len(indices)):
            for j in range(i + 1, len(indices)):
                x1, x2 = points[indices[i]][0], points[indices[j]][0]
                if x1 != x2:
                    triangles += len(x_count[x1]) - 1
                    triangles += len(x_count[x2]) - 1

    return triangles // 2

