def count_right_triangles(N, points):
    x_coords = defaultdict(list)
    y_coords = defaultdict(list)

    for x, y in points:
        x_coords[x].append(y)
        y_coords[y].append(x)

    count = 0

    for x in x_coords:
        y_count = defaultdict(int)
        for y in x_coords[x]:
            y_count[y] += 1

        for y1 in x_coords[x]:
            for y2 in x_coords[x]:
                if y1 != y2:
                    count += y_count[y1] * y_count[y2]

    for y in y_coords:
        x_count = defaultdict(int)
        for x in y_coords[y]:
            x_count[x] += 1

        for x1 in y_coords[y]:
            for x2 in y_coords[y]:
                if x1 != x2:
                    count += x_count[x1] * x_count[x2]

    return count

